EXPECTED_SIZE = 158550  # exact byte size of the embedded entry.png
PNG_SIGNATURE = b"\x89PNG\r\n\x1a\n"


def main():
    data = base64.b85decode(_PAYLOAD_B85.encode("ascii"))
    # Self-check: the decoded payload must be the intact front page.
    if len(data) != EXPECTED_SIZE or not data.startswith(PNG_SIGNATURE):
        raise SystemExit(
            f"payload self-check failed: {len(data)} bytes "
            f"(expected {EXPECTED_SIZE})")
    if len(sys.argv) > 1:
        out_dir = sys.argv[1]
    else:
        out_dir = os.environ.get("OUTPUT_DIR", "/output")
    os.makedirs(out_dir, exist_ok=True)
    path = os.path.join(out_dir, "entry.png")
    with open(path, "wb") as fh:
        fh.write(data)
    print(f"wrote {path} ({len(data)} bytes)")


if __name__ == "__main__":
    main()
